import io
import runpy
import sys
import unittest
from unittest.mock import patch

DESIRED = "['Arise', 'But', 'It', 'Juliet', 'Who', 'already', 'and', 'breaks', 'east', 'envious', 'fair', 'grief', 'is', 'kill', 'light', 'moon', 'pale', 'sick', 'soft', 'sun', 'the', 'through', 'what', 'window', 'with', 'yonder']"
DESIRED2 = None
STDIN = "romeo.txt\n"


def run_student(stdin=STDIN):
    output = io.StringIO()
    with patch('builtins.input', side_effect=_input_side_effect(stdin)):
        with patch('sys.stdout', output):
            try:
                runpy.run_path('student.py', run_name='__main__')
            except SystemExit:
                pass
    return output.getvalue()


def _input_side_effect(stdin):
    lines = stdin.splitlines()
    # Preserve trailing blank semantics for programs that call input() once per line
    if stdin.endswith('\n'):
        # splitlines drops final empty; reconstruct queue of lines without newlines
        pass
    queue = list(lines)

    def _input(prompt=''):
        if not queue:
            raise EOFError('EOF when reading a line')
        return queue.pop(0)

    return _input


class OutputTests(unittest.TestCase):
    def test_desired_output(self):
        got = run_student().rstrip()
        # Normalize trailing whitespace per line for friendlier comparison
        got_norm = '\n'.join(line.rstrip() for line in got.splitlines()).rstrip()
        want = DESIRED.rstrip() if isinstance(DESIRED, str) else DESIRED
        alts = [want]
        if DESIRED2:
            alts.append(DESIRED2.rstrip())
        if got_norm not in alts:
            self.assertEqual(got_norm, want)


class SourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open('student.py', encoding='utf-8') as f:
            cls.src = f.read()

    def test_source_split(self):
        self.assertIn("split", self.src,
            "You should use split() to break each line into words.")

    def test_source_append(self):
        self.assertIn("append", self.src,
            "You should use append() to add the word to the list if it is not there.")

    def test_source_not_extend(self):
        self.assertNotIn("extend", self.src,
            "You should not use extend() in this assignment.")

    def test_source_open(self):
        self.assertIn("open", self.src,
            "You need to use open() to open the file.")

    def test_source_sort(self):
        self.assertIn("sort", self.src,
            "You need to use sort() to sort the list before you print it out.")

    def test_source_not_yonder(self):
        self.assertNotIn("'yonder'", self.src,
            "You should not put the output data in strings")

    def test_source_not_remove(self):
        self.assertNotIn(".remove(", self.src,
            "You should not need to use the remove() method")

    def test_source_not_set(self):
        self.assertNotIn(".set(", self.src,
            "You should not need to use the set() method")

    def test_source_for(self):
        self.assertIn("for", self.src,
            "You need two for loops. One for the lines and one for the words on each line.")
